%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[HN_FFCutsFits,CutFitFileHN] = recover_selected_cuts('HN_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(HN_FFCutsFits);
nf = 11 %[output:888861f2]
%for i = 11:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei800_offH1H0_HNmaxFF' %[output:3b59efcf]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('ProcessiHN cuts: %s \n', selectCuts); %[output:1fa9b020]
cuts_list = HN_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;        
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;            
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei = 70;            
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:3ed3cc30]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 0.3; keep_figure; %[output:1f0bbdf4]
end %[output:group:3ed3cc30]
dir_name  = "HN";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
en_mm(1) = 150;
%en_mm(2) = 380;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
HN_FFCutsFits.(selectCuts) = cuts_list;
%%
HN_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:90f5422d] %[output:09cb3be4] %[output:0738fad3] %[output:51c9c43f] %[output:7072cad4] %[output:2c5819a8] %[output:18fd6384] %[output:8695e509] %[output:0293a3e8] %[output:6f8c8727] %[output:30014311] %[output:146ae6d7] %[output:7aa2ecbb] %[output:3dc467f5] %[output:755d26e5] %[output:94679e7e] %[output:770fb75b] %[output:51273fad] %[output:8795c227] %[output:4133d441] %[output:2b2b83c8] %[output:805e58ac] %[output:30d45723] %[output:59541b23] %[output:4e3364cb] %[output:096986b2] %[output:61971881] %[output:48597ffc] %[output:0ab32c2a] %[output:8102206a] %[output:4789cb72] %[output:8125b6c1] %[output:86ae8cd9] %[output:506bf8b3] %[output:4e0ae276] %[output:5e771870] %[output:2fe93763] %[output:8a599b2a] %[output:84b06617] %[output:7d74d686] %[output:34a35572] %[output:1579dace] %[output:86959cbf] %[output:204dd7cd] %[output:24962903] %[output:7d182ccc] %[output:98401f59] %[output:09ce9215] %[output:3f19ea63]
    HN_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:90f5422d] %[output:09cb3be4] %[output:0738fad3] %[output:51c9c43f] %[output:7072cad4] %[output:2c5819a8] %[output:18fd6384] %[output:8695e509] %[output:0293a3e8] %[output:6f8c8727] %[output:30014311] %[output:146ae6d7] %[output:7aa2ecbb] %[output:3dc467f5] %[output:755d26e5] %[output:94679e7e] %[output:770fb75b] %[output:51273fad] %[output:8795c227] %[output:4133d441] %[output:2b2b83c8] %[output:805e58ac] %[output:30d45723] %[output:59541b23] %[output:4e3364cb] %[output:096986b2] %[output:61971881] %[output:48597ffc] %[output:0ab32c2a] %[output:8102206a] %[output:4789cb72] %[output:8125b6c1] %[output:86ae8cd9] %[output:506bf8b3] %[output:4e0ae276] %[output:5e771870] %[output:2fe93763] %[output:8a599b2a] %[output:84b06617] %[output:7d74d686] %[output:34a35572] %[output:1579dace] %[output:86959cbf] %[output:204dd7cd] %[output:24962903] %[output:7d182ccc] %[output:98401f59] %[output:09ce9215] %[output:3f19ea63]
cl = HN_FFCutsFits.(selectCuts);
HN_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep
%%

all_fit_par = HN_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);ly 0 0.05; keep_figure; %[output:445a8e9e]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:0ef0ca80]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_HN.m';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_HN_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;
%end
%%
fit_src_struc = HN_FFCutsFits;
save(CutFitFileHN,"fit_src_struc",'-v7.3')

